def _duplicate_row(grid, target, col):
    best = None
    for i, row in enumerate(grid):
        if i == target or row[col] == 6:
            continue
        pairs = [(a, b) for a, b in zip(grid[target], row) if a != 6 and b != 6]
        if len(pairs) >= 8 and all(a == b for a, b in pairs):
            score = len(pairs)
            if best is None or score > best[0]:
                best = (score, row[col])
    return None if best is None else best[1]


def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] != 6:
                continue
            value = grid[c][r]
            if value == 6:
                value = _duplicate_row(grid, r, c)
            if value is None or value == 6:
                value = _duplicate_row(grid, c, r)
            if (value is None or value == 6) and r == c and c + 1 < len(grid[r]):
                value = grid[r][c + 1]
            if value is not None and value != 6:
                out[r][c] = value
    return out
